import adsk.core, adsk.fusion, json
def cut_ext(root,sk,dist,body,name):
    ex=root.features.extrudeFeatures
    inp=ex.createInput(sk.profiles.item(0),adsk.fusion.FeatureOperations.CutFeatureOperation)
    inp.setDistanceExtent(False,adsk.core.ValueInput.createByReal(dist))
    inp.participantBodies=[body]
    f=ex.add(inp); f.name=name; return f
def find_sketch(root,name):
    for sk in root.sketches:
        if sk.name==name: return sk
    return None
def find_top(root):
    for b in root.bRepBodies:
        if b.name=='RIGHT_TRACKBALL_CASE_TOP': return b
    for b in root.bRepBodies:
        if b.boundingBox.minPoint.z>1.0: return b
    return None
def run(_context):
    app=adsk.core.Application.get(); out=[]
    for i in range(app.documents.count):
        doc=app.documents.item(i)
        des=adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType'))
        if not des: continue
        root=des.rootComponent; bottom=None
        for b in root.bRepBodies:
            if b.name=='RIGHT_TRACKBALL_CASE_BOTTOM': bottom=b
        if not bottom: continue
        doc.activate(); top=find_top(root); action=[]
        if not top:
            out.append({'case':'right','error':'top body not found'}); continue
        top.name='RIGHT_TRACKBALL_CASE_TOP'
        for skname,featname in [('RIGHT_CASE_TOP_OPENING','RIGHT_CASE_TOP_OPENING'),('RIGHT_TOP_TRACKBALL_OPENING','RIGHT_TOP_TRACKBALL_CUT')]:
            sk=find_sketch(root,skname)
            if sk:
                try: cut_ext(root,sk,0.35,top,featname); action.append('cut:'+featname)
                except Exception as e: action.append('error:'+featname+':'+str(e))
                sk.isVisible=False
        mgr=des.exportManager; base='/Users/daiki/Projects/sage60/mechanical/gasket_v1/'
        stl=bool(mgr.execute(mgr.createSTLExportOptions(top,base+'sage60_right_tb_case_top.stl')))
        step=bool(mgr.execute(mgr.createSTEPExportOptions(base+'sage60_right_tb_case_complete.step',root)))
        out.append({'case':'right','top':top.name,'action':action,'stl':stl,'completeStep':step})
    print(json.dumps(out))
